const fields = ['name','first_name','company','phone','email','city','industry'];
function phone(value, options = {}) {
  if (typeof value !== 'string') throw new Error('Phone must be text; format Excel phone cells as Text');
  let p = value.trim();
  if (!/^[+\d\s().-]+$/.test(p)) throw new Error('Phone contains unsupported characters');
  p = p.replace(/[\s().-]/g,'');
  if (p.startsWith('00')) p = '+' + p.slice(2);
  if (!p.startsWith('+')) {
    if (options.phoneFormat === 'international') p = '+' + p;
    else if (/^[1-9]\d{0,2}$/.test(options.defaultCallingCode || '')) {
      const trunk = options.trunkPrefix || '';
      if (trunk && !/^\d{1,3}$/.test(trunk)) throw new Error('Invalid trunkPrefix');
      if (trunk && p.startsWith(trunk)) p = p.slice(trunk.length);
      p = '+' + options.defaultCallingCode + p;
    } else throw new Error('Use +country-code or specify defaultCallingCode');
  }
  if (!/^\+[1-9]\d{7,14}$/.test(p)) throw new Error('Invalid international phone length');
  return p;
}
function clean(value, max = 200) {
  const s = String(value ?? '').normalize('NFKC').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g,'').trim();
  if (s.length > max) throw new Error('Field exceeds ' + max + ' characters');
  if (s.includes('{{') || s.includes('}}')) throw new Error('Contact data cannot contain template delimiters');
  return s;
}
function normalizeContacts(rows, options = {}) {
  if (!Array.isArray(rows) || !rows.length || rows.length > 5000) throw new Error('Import 1-5000 rows per request');
  const seen = new Set(), contacts = [], rejected = []; let duplicates = 0;
  rows.forEach((raw, i) => {
    try {
      if (!raw || typeof raw !== 'object' || Array.isArray(raw)) throw new Error('Invalid contact');
      const row = Object.fromEntries(Object.entries(raw).map(([k,v])=>[k.replace(/^\uFEFF/,'').trim().toLowerCase().replace(/\s+/g,'_'),v]));
      const c = {};
      for (const k of fields) c[k] = k === 'phone' ? phone(row[k], options) : clean(row[k], k === 'email' ? 254 : 200);
      c.first_name ||= c.name.split(/\s+/)[0] || '';
      if (c.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email)) throw new Error('Invalid email');
      if (seen.has(c.phone)) { duplicates++; return; }
      seen.add(c.phone); contacts.push(c);
    } catch (e) { rejected.push({row:i+2,error:e.message}); }
  });
  return {contacts,validation:{received:rows.length,valid:contacts.length,duplicates,rejectedCount:rejected.length,rejected:rejected.slice(0,100),errorsTruncated:rejected.length>100}};
}
function normalizeTemplate(value) {
  if (typeof value !== 'string' || !value.trim() || value.length>4096) throw new Error('Template must contain 1-4096 characters');
  const t = value.replace(/\{\{\s*([a-z_]+)\s*\}\}/g, (_,k) => {
    if (!fields.includes(k)) throw new Error('Unsupported template variable: '+k);
    return '{{'+k+'}}';
  });
  if (/\{\{|\}\}/.test(t.replace(/\{\{[a-z_]+\}\}/g,''))) throw new Error('Malformed template');
  return t;
}

